        valid_transition: |obj, old_obj: DynamicObjectView| T::unmarshal(obj)->Ok_0.transition_validation(T::unmarshal(old_obj)->Ok_0),
        marshalled_default_status: || T::marshal_status(T::default().status()),
    }
